def apply():
    byfile = {}
    for fname, kind, anchor, payload in OPS:
        byfile.setdefault(fname, []).append((kind, anchor, payload))
    for fname, ops in byfile.items():
        path = os.path.join(HERE, fname)
        with open(path, encoding='utf-8') as f:
            lines = f.read().split('\n')
        for kind, anchor, payload in ops:
            hits = [i for i, l in enumerate(lines) if anchor in l]
            assert len(hits) == 1, f'{fname}: anchor match {len(hits)} != 1: {anchor[:60]}'
            i = hits[0]
            if kind == 'replace':
                lines[i] = payload
            elif kind == 'delete':
                del lines[i]
            elif kind == 'delete_block':
                j = i
                while not lines[j].rstrip().endswith('None),'):
                    j += 1
                    assert j - i < 30, 'block end not found'
                del lines[i:j + 1]
            elif kind == 'insert_after':
                lines.insert(i + 1, payload)
            elif kind == 'sub':
                old, new = payload
                assert lines[i].count(old) == 1, f'{fname}: sub count != 1: {old}'
                lines[i] = lines[i].replace(old, new)
        with open(path, 'w', encoding='utf-8') as f:
            f.write('\n'.join(lines))
        print(f'{fname}: {len(ops)} ops applied')


if __name__ == '__main__':
    apply()
